"""Agrega la subarea HAREFIELD a app.html (Lumen). Idempotente: si ya esta aplicado, no toca nada.
Uso:  cd lumen-repo ; python patch_app_harefield.py"""
import io, sys, os
P = 'app.html'
if not os.path.exists(P):
    sys.exit('No encuentro app.html en esta carpeta. Corre el script parado en lumen-repo.')
s = io.open(P, encoding='utf-8', newline='').read()
if "clase: 'harefield'" in s:
    print('app.html ya tiene la subarea HAREFIELD. Nada que hacer.'); sys.exit(0)
